package cbp

// Identity: a client can use either a flat identity issued by the main node or
// a portable bundle generated by a standalone edge node's `keygen` command.
// The bundle carries the client key pair, the node auth token, the node
// endpoints and an optional TLS CA path, so an independent edge needs no
// identity server at all. The flat form is kept for the central flow, where the
// key pair is issued on first use and cached locally.

import (
	"bytes"
	"context"
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// ClientIdentity is one client key pair in the flat cache form. A standalone
// bundle is flattened into this type by ClientIdentityBundle.ClientIdentity.
type ClientIdentity struct {
	ClientID   string   `json:"client_id"`
	PublicKey  string   `json:"public_key"`
	PrivateKey string   `json:"private_key"`
	Regions    []string `json:"regions,omitempty"`
}

// ClientIdentityBundle is the portable file written by a standalone edge's
// `cbpserver keygen`. Its nested shape is deliberately different from the
// cache file: the private key belongs to the client, while the token and CA
// belong to the node. Flattening it would lose the endpoint and token data the
// client needs to connect without a control-plane account.
type ClientIdentityBundle struct {
	Schema   string `json:"schema,omitempty"`
	ClientID string `json:"client_id"`
	Client   struct {
		PrivateKey string `json:"private_key"`
		PublicKey  string `json:"public_key"`
	} `json:"client"`
	Node struct {
		ID              string `json:"id,omitempty"`
		PublicKey       string `json:"public_key,omitempty"`
		ControlEndpoint string `json:"control_endpoint,omitempty"`
		DataEndpoint    string `json:"data_endpoint,omitempty"`
		AuthToken       string `json:"auth_token,omitempty"`
		TLSCAFile       string `json:"tls_ca_file,omitempty"`
	} `json:"node"`
}

// IdentityMetadata is the node-side data a bundle carries. It never includes
// the client private key.
type IdentityMetadata struct {
	NodeID          string
	NodePublicKey   string
	ControlEndpoint string
	DataEndpoint    string
	AuthToken       string
	TLSCAFile       string
}

// ClientIdentity flattens the client half of the bundle.
func (b ClientIdentityBundle) ClientIdentity() ClientIdentity {
	return ClientIdentity{
		ClientID:   strings.TrimSpace(b.ClientID),
		PublicKey:  strings.TrimSpace(b.Client.PublicKey),
		PrivateKey: strings.TrimSpace(b.Client.PrivateKey),
	}
}

// Metadata returns the node half of the bundle.
func (b ClientIdentityBundle) Metadata() IdentityMetadata {
	return IdentityMetadata{
		NodeID:          strings.TrimSpace(b.Node.ID),
		NodePublicKey:   strings.TrimSpace(b.Node.PublicKey),
		ControlEndpoint: strings.TrimSpace(b.Node.ControlEndpoint),
		DataEndpoint:    strings.TrimSpace(b.Node.DataEndpoint),
		AuthToken:       strings.TrimSpace(b.Node.AuthToken),
		TLSCAFile:       strings.TrimSpace(b.Node.TLSCAFile),
	}
}

// LoadClientIdentity reads either identity shape. It reports found=false only
// when the path does not exist; a malformed or incomplete file is an error.
// The nested bundle shape is detected by its `client` object, so a flat cache
// file remains byte-for-byte compatible.
func LoadClientIdentity(path string) (ClientIdentity, IdentityMetadata, bool, error) {
	path = strings.TrimSpace(path)
	if path == "" {
		return ClientIdentity{}, IdentityMetadata{}, false, errors.New("cbp: identity file path is required")
	}
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return ClientIdentity{}, IdentityMetadata{}, false, nil
	}
	if err != nil {
		return ClientIdentity{}, IdentityMetadata{}, false, fmt.Errorf("cbp: read identity %s: %w", path, err)
	}

	var top map[string]json.RawMessage
	if err := json.Unmarshal(data, &top); err != nil {
		return ClientIdentity{}, IdentityMetadata{}, true, fmt.Errorf("cbp: parse identity %s: %w", path, err)
	}
	if _, ok := top["client"]; ok {
		var bundle ClientIdentityBundle
		if err := json.Unmarshal(data, &bundle); err != nil {
			return ClientIdentity{}, IdentityMetadata{}, true, fmt.Errorf("cbp: parse identity bundle %s: %w", path, err)
		}
		identity := bundle.ClientIdentity()
		if err := validateIdentity(identity); err != nil {
			return ClientIdentity{}, IdentityMetadata{}, true, fmt.Errorf("cbp: identity bundle %s: %w", path, err)
		}
		return identity, bundle.Metadata(), true, nil
	}

	var identity ClientIdentity
	if err := json.Unmarshal(data, &identity); err != nil {
		return ClientIdentity{}, IdentityMetadata{}, true, fmt.Errorf("cbp: parse identity %s: %w", path, err)
	}
	if err := validateIdentity(identity); err != nil {
		return ClientIdentity{}, IdentityMetadata{}, true, fmt.Errorf("cbp: identity %s: %w", path, err)
	}
	return identity, IdentityMetadata{}, true, nil
}

// IdentityConfig says where the key is cached and where to ask for one.
type IdentityConfig struct {
	FilePath  string
	ServerURL string
	Token     string
	ClientID  string
	Regions   []string
	HTTP      *http.Client
	Timeout   time.Duration
}

// LoadOrIssueClient reads the cached identity, or requests one from the server
// when the cache file does not exist. A present but malformed file is an error
// rather than a reason to request a second key.
func LoadOrIssueClient(ctx context.Context, cfg IdentityConfig) (ClientIdentity, error) {
	path := strings.TrimSpace(cfg.FilePath)
	if path == "" {
		return ClientIdentity{}, errors.New("cbp: identity file path is required")
	}
	identity, _, found, err := LoadClientIdentity(path)
	if err != nil {
		return ClientIdentity{}, err
	}
	if found {
		return identity, nil
	}

	if strings.TrimSpace(cfg.ServerURL) == "" {
		return ClientIdentity{}, fmt.Errorf("cbp: no identity file %s and no identity server to issue one", path)
	}
	reqBody, err := json.Marshal(struct {
		ClientID string   `json:"client_id"`
		Regions  []string `json:"regions,omitempty"`
	}{ClientID: strings.TrimSpace(cfg.ClientID), Regions: cfg.Regions})
	if err != nil {
		return ClientIdentity{}, fmt.Errorf("cbp: encode issue request: %w", err)
	}
	endpoint := strings.TrimRight(strings.TrimSpace(cfg.ServerURL), "/") + "/v1/identity/client"
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(reqBody))
	if err != nil {
		return ClientIdentity{}, fmt.Errorf("cbp: create issue request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if cfg.Token != "" {
		req.Header.Set("Authorization", "Bearer "+cfg.Token)
	}
	client := cfg.HTTP
	if client == nil {
		timeout := cfg.Timeout
		if timeout <= 0 {
			timeout = 15 * time.Second
		}
		client = &http.Client{Timeout: timeout}
	}
	resp, err := client.Do(req)
	if err != nil {
		return ClientIdentity{}, fmt.Errorf("cbp: issue client identity: %w", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 64*1024))
	if err != nil {
		return ClientIdentity{}, fmt.Errorf("cbp: read issue response: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		return ClientIdentity{}, fmt.Errorf("cbp: issue client identity: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	var issued ClientIdentity
	if err := json.Unmarshal(body, &issued); err != nil {
		return ClientIdentity{}, fmt.Errorf("cbp: parse issue response: %w", err)
	}
	if err := validateIdentity(issued); err != nil {
		return ClientIdentity{}, fmt.Errorf("cbp: server returned invalid identity: %w", err)
	}
	if err := SaveClientIdentity(path, issued); err != nil {
		return ClientIdentity{}, err
	}
	return issued, nil
}

// SaveClientIdentity writes the identity atomically with mode 0600.
func SaveClientIdentity(path string, identity ClientIdentity) error {
	if err := validateIdentity(identity); err != nil {
		return err
	}
	raw, err := json.MarshalIndent(identity, "", "  ")
	if err != nil {
		return fmt.Errorf("cbp: encode identity: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return fmt.Errorf("cbp: create identity directory: %w", err)
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, raw, 0600); err != nil {
		return fmt.Errorf("cbp: write identity: %w", err)
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("cbp: replace identity: %w", err)
	}
	return nil
}

func validateIdentity(identity ClientIdentity) error {
	if strings.TrimSpace(identity.ClientID) == "" {
		return errors.New("client_id is required")
	}
	public, err := base64.RawURLEncoding.DecodeString(identity.PublicKey)
	if err != nil || len(public) != ed25519.PublicKeySize {
		return errors.New("invalid public_key")
	}
	seed, err := base64.RawURLEncoding.DecodeString(identity.PrivateKey)
	if err != nil || len(seed) != ed25519.SeedSize {
		return errors.New("invalid private_key")
	}
	derived := ed25519.NewKeyFromSeed(seed).Public().(ed25519.PublicKey)
	if !bytes.Equal(derived, public) {
		return errors.New("private_key does not match public_key")
	}
	return nil
}

// IdentityKey decodes the persisted seed into a usable private key.
func (identity ClientIdentity) IdentityKey() (ed25519.PrivateKey, error) {
	seed, err := base64.RawURLEncoding.DecodeString(identity.PrivateKey)
	if err != nil {
		return nil, fmt.Errorf("cbp: decode identity seed: %w", err)
	}
	if len(seed) != ed25519.SeedSize {
		return nil, errors.New("cbp: identity seed has wrong length")
	}
	return ed25519.NewKeyFromSeed(seed), nil
}
